function photo(folder, slug, key, filename, alt, caption) {
  const [file, author, license] = commons[key];
  const safeTitle = file.replaceAll(" ", "_");
  return {
    src: `/images/news/articles/${folder}/${slug}/${filename}.webp`,
    sourceUrl: `https://commons.wikimedia.org/wiki/Special:FilePath/${encodeURIComponent(file)}`,
    alt, caption, width: 1920, height: 1280,
    credit: { label: license === "Domaine public" ? "Photo : Domaine public" : `Photo : ${author} — ${license}`, href: `https://commons.wikimedia.org/wiki/File:${encodeURIComponent(safeTitle)}` },
  };
}

function normalizeInlineLink(value) {
  if (typeof value !== "string") return value;
  const match = value.match(/^(.*?)\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)(.*)$/);
  return match ? { before: match[1], anchor: match[2], href: match[3], after: match[4] } : value;
}

