function profile({ slug, title, metaTitle, folder, category, categoryHref, publishedAt = "2026-10-27", photos, intro, sections, outro }) {
  const additions = editorialAdditions[slug];
  if (additions) {
    const normalizedIntro = typeof intro === "string" ? { before: intro } : intro;
    intro = normalizedIntro.anchor && normalizedIntro.href
      ? { ...normalizedIntro, after: `${normalizedIntro.after || ""} ${additions.intro.trim()}` }
      : { ...normalizedIntro, before: `${normalizedIntro.before || ""} ${additions.intro.trim()}` };
    sections = sections.map((section, index) => ({ ...section, paragraphs: [...section.paragraphs, additions.sections[index]] }));
    outro = `${outro} ${additions.outro.trim()}`;
  }
  const finishingParagraphs = editorialFinishingParagraphs[slug];
  if (finishingParagraphs) sections = sections.map((section, index) => ({ ...section, paragraphs: [...section.paragraphs, finishingParagraphs[index]] }));
  if (closingExtensions[slug]) outro = `${outro} ${closingExtensions[slug].trim()}`;
  if (qualityPassOutros[slug]) outro = qualityPassOutros[slug];
  const qualityParagraphs = qualityPassParagraphs[slug];
  if (qualityParagraphs) sections = sections.map((section, index) => ({ ...section, paragraphs: qualityParagraphs[index] ? [...section.paragraphs, qualityParagraphs[index]] : section.paragraphs }));
  const folderPath = folder;
  const photoMap = Object.fromEntries(["hero", "leftTop", "leftBottom", "rightTall"].map((key) => [key, photo(folderPath, slug, ...photos[key]) ]));
  const normalizedIntroValue = typeof intro === "string" ? normalizeInlineLink(intro) : (intro.href ? intro : normalizeInlineLink(intro.before) || intro);
  const normalizedIntro = typeof normalizedIntroValue === "string" ? { before: normalizedIntroValue } : normalizedIntroValue;
  return {
    slug, title, metaTitle: metaTitle || `${title} | Soul Music Quiz`, cardTitle: title,
    description: normalizedIntro.before.slice(0, 155).trim(), category: { label: category, href: categoryHref }, author: "Deezy",
    publishedAt, publishedLabel: "27 octobre 2026", updatedLabel: "27 octobre 2026", returnHref: categoryHref,
    listingImage: photoMap.hero.src, listingAlt: photoMap.hero.alt, photos: photoMap, intro: normalizedIntro,
    blocks: [
      { type: "heading", text: sections[0].heading }, { type: "paragraphs", items: sections[0].paragraphs.map(normalizeInlineLink) },
      { type: "figure", photo: "leftTop", mobileOnly: true },
      { type: "heading", text: sections[1].heading }, { type: "paragraphs", items: sections[1].paragraphs.map(normalizeInlineLink) },
      { type: "figure", photo: "leftBottom", mobileOnly: true },
      { type: "figurePair", photos: ["leftTop", "leftBottom", "rightTall"] },
      { type: "heading", text: sections[2].heading }, { type: "paragraphs", items: sections[2].paragraphs.map(normalizeInlineLink) },
    ],
    outro,
  };
}

